DECLARE
  paquete jsonb := $polo${"ley":{"id":"172a0b68-5ef3-5a43-841f-eecf288f0894","siglas":"PODECOBI-DISTRITO-FINANCIERO-Y-TECNOLOGICO-DE-CANCUN","titulo":"ACUERDO por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Distrito Financiero y Tecnológico de Cancún, Quintana Roo.","tipo":"acuerdo","fecha_publicacion":"2026-08-07","url_original":"https://sidof.segob.gob.mx/notas/docFuente/5795731","temas_clave":["PODECOBI","Declaratoria","Distrito Financiero y Tecnológico de Cancún","Quintana Roo"]},"articulos":[{"id":"526c07bc-4e34-5454-bf25-7871dd9c6e6b","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Preámbulo y considerandos","contenido":"<p>ACUERDO por el que se emite la Declaratoria del Polo de Desarrollo Económico para el Bienestar Distrito Financiero y Tecnológico de Cancún, Quintana Roo.</p>\n<p>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Economía.</p>\n<p>MARCELO LUIS EBRARD CASAUBON, Secretario de Economía, con fundamento en los artículos 34 de la Ley Orgánica de la Administración Pública Federal; Primero, segundo párrafo, Décimo, tercer párrafo del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar; 5, fracciones XVII y XXIV, del Reglamento Interior de la Secretaría de Economía, y los lineamientos 2 fracción XIV, 4, fracción II, 8, segundo párrafo del Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar y</p>\n<p>CONSIDERANDO</p>\n<p>Que de conformidad con lo dispuesto en los artículos 25 y 26, apartado A de la Constitución Política de los Estados Unidos Mexicanos, corresponde al Estado la rectoría del desarrollo nacional mediante la competitividad, el fomento del crecimiento económico, el empleo, así como una justa distribución del ingreso y la riqueza, para garantizar que ésta sea integral y sustentable y que permita el pleno ejercicio de la libertad y la dignidad de los individuos, grupos y clases sociales. Al desarrollo económico nacional concurrirán, con responsabilidad social, el sector público, el sector social y el sector privado, sin menoscabo de otras formas de actividad económica que contribuyan al desarrollo de la Nación;</p>\n<p>Que el Plan Nacional de Desarrollo(1) 2025-2030, publicado en el Diario Oficial de la Federación (DOF) el 15 de abril de 2025, considera al \"Plan México\" como una herramienta de largo plazo que sustenta una estrategia de industrialización en el país incrementando la participación de empresas mexicanas en la cadena de proveeduría de las exportaciones y en la generación de productos para consumo nacional; permitiendo a las empresas nacionales, desde micro, pequeñas y medianas hasta grandes corporaciones, tener un papel más activo en la manufactura de bienes intermedios, insumos y componentes esenciales;</p>\n<p>Que en ese sentido el \"Plan México\", presentado por la Presidenta de los Estados Unidos Mexicanos el 13 de enero de 2025, es una estrategia de desarrollo nacional que busca fortalecer el mercado interno y los mercados regionales para posicionar a México entre las diez principales economías del mundo y reducir la pobreza y la desigualdad. Esta estrategia también busca promover el desarrollo económico sostenible y equitativo en todo el país; generar empleos dignos y bien remunerados; fortalecer el progreso científico, tecnológico y la innovación; ampliar el acceso a la educación media superior y superior y su vínculo con el Plan Nacional de Desarrollo, a fin de alcanzar el bienestar de las mexicanas y los mexicanos;</p>\n<p>Que el \"Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar\"; publicado el 22 de mayo de 2025 en el DOF y su reforma publicada en el mismo medio de difusión oficial el 31 de julio de 2025; establece que, se brindan beneficios tributarios a los contribuyentes que realicen actividades económicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar y a las personas morales que hayan obtenido Autorización que los acredite como Desarrolladores;</p>\n<p>Que, en la misma fecha, se publicó en el DOF el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, el cual fue modificado mediante diverso publicado en el mismo órgano de difusión oficial el 29 de agosto de 2025;</p>\n<p>Que en el Programa Sectorial de Economía 2025-2030, publicado en el DOF el 22 de diciembre de 2025, se establecen objetivos prioritarios, estrategias y líneas de acción orientadas al cumplimiento de los 100 Compromisos para el Segundo Piso de la Cuarta Transformación del Gobierno de México, entre los cuales se prevé la implementación de iniciativas estratégicas como el Plan Sonora, los procesos de relocalización industrial y la creación de Polos de Desarrollo Económico para el Bienestar en regiones estratégicas del país, a efecto de impulsar un crecimiento regional equilibrado, en congruencia con los principios de justicia social, reducción de desigualdades y sustentabilidad previstos en el Plan Nacional de Desarrollo, particularmente en el eje denominado \"República próspera y conectada\";</p>\n<p>Que en la Primera Sesión Ordinaria 2026 del Comité Intersecretarial de Promoción, celebrada el 17 de marzo de 2026, fue aprobado el Dictamen Colegiado correspondiente al Polo de Desarrollo Económico para el Bienestar Distrito Financiero y Tecnológico de Cancún, Quintana Roo, y</p>\n<p>Que con el objetivo de impulsar la competitividad y favorecer la operación de los contribuyentes que realicen actividades económicas productivas al interior de los Polos de Desarrollo Económico para el Bienestar y de los Desarrolladores, así como en el ejercicio de la facultad establecida en el artículo 34 de la Ley Orgánica de la Administración Pública Federal, he tenido a bien expedir el siguiente:</p>\n<p>ACUERDO POR EL QUE SE EMITE LA DECLARATORIA DEL POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, QUINTANA ROO</p>","tipo_articulo":"preambulo","orden":1,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"df3fc4d0-c1b6-5ca4-ab59-8648d86eedf9","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo primero","contenido":"<p>ARTÍCULO PRIMERO. El presente Acuerdo tiene por objeto declarar como Polo de Desarrollo Económico para el Bienestar Distrito Financiero y Tecnológico de Cancún, Quintana Roo, al polígono que se describe en el artículo siguiente.</p>","tipo_articulo":"ordinario","orden":2,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"5e9e5384-6d74-590f-a7c0-cac788a12e82","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo segundo","contenido":"<p>ARTÍCULO SEGUNDO. Se declara como Polo de Desarrollo Económico para el Bienestar Distrito Financiero y Tecnológico de Cancún, Quintana Roo (PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN) a la superficie de 60.76 hectáreas (sesenta hectáreas, setenta y siete áreas). El PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, se encuentra ubicado en el municipio de Benito Juárez, en el estado de Quintana Roo, de conformidad con los cuadros de construcción y el croquis de ubicación siguientes:</p>\n<p>CROQUIS DE UBICACIÓN - DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN</p>\n<p><a href=\"https://dof.gob.mx/abrirPDF.php?anio=2026&amp;archivo=07082026-MAT.pdf&amp;repo=#page=75\">Croquis de ubicación en el PDF oficial · página 75</a></p>\n<p>Gobierno del Estado de Quintana Roo, 2026</p>","tipo_articulo":"ordinario","orden":3,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"c874095d-73e2-5a1b-8532-de706d675500","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero","contenido":"<p>ARTÍCULO TERCERO. La superficie a que se refiere el artículo anterior cumple los criterios de selección establecidos en el Acuerdo por el que se emiten los Lineamientos para los Polos de Desarrollo Económico para el Bienestar, publicado en el Diario Oficial de la Federación el 22 de mayo de 2025 y reformado mediante diverso publicado en el mismo órgano de difusión oficial el 29 de agosto de 2025, como a continuación se señala:</p>","tipo_articulo":"ordinario","orden":4,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"e9556bde-045c-56a0-967a-dfb2e0c2a697","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · I. Criterio de Macro Localización","contenido":"<p>I. Criterio de Macro Localización</p>\n<table><thead><tr><th colspan=\"3\">Cuadro de Construcción Kulkaná 1</th></tr><tr><th rowspan=\"2\">Vértice</th><th colspan=\"2\">Coordenadas</th></tr><tr><th>X</th><th>Y</th></tr></thead><tbody><tr><td>1</td><td>4058128.4721</td><td>1083216.9955</td></tr><tr><td>2</td><td>4057609.8315</td><td>1083137.0803</td></tr><tr><td>3</td><td>4057563.7578</td><td>1083581.5033</td></tr><tr><td>4</td><td>4057602.3597</td><td>1083593.4264</td></tr><tr><td>5</td><td>4057683.1282</td><td>1083614.4076</td></tr><tr><td>6</td><td>4057714.9622</td><td>1083635.7433</td></tr><tr><td>7</td><td>4057777.6593</td><td>1083651.1424</td></tr><tr><td>8</td><td>4057966.1079</td><td>1083678.4081</td></tr><tr><td>9</td><td>4058040.1165</td><td>1083694.3723</td></tr><tr><td>10</td><td>4058053.5504</td><td>1083596.8104</td></tr><tr><td>11</td><td>4058072.3280</td><td>1083482.4640</td></tr><tr><td>12</td><td>4058094.2019</td><td>1083368.6690</td></tr><tr><td>13</td><td>4058106.2948</td><td>1083312.0045</td></tr><tr><td>14</td><td>4058128.4721</td><td>1083216.9955</td></tr><tr><td>15</td><td>4058225.9988</td><td>1083232.0250</td></tr><tr><td>16</td><td>4058197.6148</td><td>1083227.6513</td></tr><tr><td>17</td><td>4058174.3224</td><td>1083327.2440</td></tr><tr><td>18</td><td>4058151.2949</td><td>1083438.8801</td></tr><tr><td>19</td><td>4058131.3054</td><td>1083551.1000</td></tr><tr><td>20</td><td>4058114.3684</td><td>1083663.8207</td></tr><tr><td>21</td><td>4058108.5016</td><td>1083709.1237</td></tr><tr><td>22</td><td>4058157.7675</td><td>1083719.7512</td></tr><tr><td>23</td><td>4058225.9988</td><td>1083232.0250</td></tr><tr><td colspan=\"3\">Superficie total: 25.91 hectáreas</td></tr></tbody></table>\n<table><thead><tr><th colspan=\"3\">Cuadro de Construcción Kulkaná 1 (Continuación)</th></tr><tr><th rowspan=\"2\">Vértice</th><th colspan=\"2\">Coordenadas</th></tr><tr><th>X</th><th>Y</th></tr></thead><tbody><tr><td>1</td><td>4058197.6184</td><td>1083227.6514</td></tr><tr><td>2</td><td>4058128.4721</td><td>1083216.9955</td></tr><tr><td>3</td><td>4058106.2919</td><td>1083312.0046</td></tr><tr><td>4</td><td>4058094.2019</td><td>1083368.6689</td></tr><tr><td>5</td><td>4058072.3280</td><td>1083482.4640</td></tr><tr><td>6</td><td>4058053.5503</td><td>1083596.8104</td></tr><tr><td>7</td><td>4058040.1165</td><td>1083694.3723</td></tr><tr><td>8</td><td>4058108.5015</td><td>1083709.1237</td></tr><tr><td>9</td><td>4058122.4545</td><td>1083607.4028</td></tr><tr><td>10</td><td>4058140.9195</td><td>1083494.9223</td></tr><tr><td>11</td><td>4058162.4299</td><td>1083382.9841</td></tr><tr><td>12</td><td>4058174.3223</td><td>1083327.2440</td></tr><tr><td>13</td><td>4058197.6184</td><td>1083227.6514</td></tr><tr><td colspan=\"3\">Superficie Total: 3.40 hectáreas</td></tr><tr><td colspan=\"3\">Cuadro de Construcción Kulkaná 2</td></tr><tr><td rowspan=\"2\">Vértice</td><td colspan=\"2\">Coordenadas</td></tr><tr><td>X</td><td>Y</td></tr><tr><td>1</td><td>4058378.7395</td><td>1082730.5022</td></tr><tr><td>2</td><td>4057662.6737</td><td>1082627.3670</td></tr><tr><td>3</td><td>4057610.1626</td><td>1083133.8857</td></tr><tr><td>4</td><td>4058129.2970</td><td>1083213.5858</td></tr><tr><td>5</td><td>4058147.0503</td><td>1083143.5259</td></tr><tr><td>6</td><td>4058162.1935</td><td>1083087.5993</td></tr><tr><td>7</td><td>4058194.8448</td><td>1082976.0754</td></tr><tr><td>8</td><td>4058230.4625</td><td>1082865.6530</td></tr><tr><td>9</td><td>4058249.3686</td><td>1082810.8837</td></tr><tr><td>10</td><td>4058278.7395</td><td>1082730.5022</td></tr><tr><td>11</td><td>4058223.8441</td><td>1083228.1031</td></tr><tr><td>12</td><td>4058243.7656</td><td>1083055.7978</td></tr><tr><td>13</td><td>4058214.5219</td><td>1083161.0640</td></tr><tr><td>14</td><td>4058198.4523</td><td>1083224.2042</td></tr><tr><td>15</td><td>4058223.8441</td><td>1083228.1031</td></tr><tr><td colspan=\"3\">Superficie Total: 28.98 hectáreas</td></tr></tbody></table>\n<table><thead><tr><th colspan=\"3\">Cuadro de Construcción Kulkaná 2 (Continuación)</th></tr><tr><th rowspan=\"2\">Vértice</th><th colspan=\"2\">Coordenadas</th></tr><tr><th>X</th><th>Y</th></tr></thead><tbody><tr><td>1</td><td>4058281.3255</td><td>1082730.9350</td></tr><tr><td>2</td><td>4058278.7395</td><td>1082730.5021</td></tr><tr><td>3</td><td>4058249.3686</td><td>1082810.8836</td></tr><tr><td>4</td><td>4058230.3112</td><td>1082866.1011</td></tr><tr><td>5</td><td>4058194.8884</td><td>1082975.9359</td></tr><tr><td>6</td><td>4058162.1935</td><td>1083087.5992</td></tr><tr><td>7</td><td>4058147.0503</td><td>1083143.5259</td></tr><tr><td>8</td><td>4058129.2970</td><td>1083213.5858</td></tr><tr><td>9</td><td>4058198.4523</td><td>1083224.2043</td></tr><tr><td>10</td><td>4058214.5219</td><td>1083161.0640</td></tr><tr><td>11</td><td>4058243.7656</td><td>1083055.7978</td></tr><tr><td>12</td><td>4058281.3255</td><td>1082730.9350</td></tr><tr><td colspan=\"3\">Superficie Total: 2.47 hectáreas</td></tr></tbody></table>\n<table><thead><tr><th colspan=\"2\">PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN</th></tr></thead><tbody><tr><td>Kulkaná 1</td><td>25.91 hectáreas</td></tr><tr><td>Continuación Kulkaná 1</td><td>3.40 hectáreas</td></tr><tr><td>Kulkaná 2</td><td>28.98 hectáreas</td></tr><tr><td>Continuación Kulkaná 2</td><td>2.47 hectáreas</td></tr><tr><td colspan=\"2\">SUPERFICIE TOTAL 60.76 HECTÁREAS</td></tr></tbody></table>\n<p>El inmueble del PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, se ubica en el municipio de Benito Juárez, estado de Quintana Roo, limita al norte con el municipio de Isla Mujeres; al oeste con el municipio de Lázaro Cárdenas; al sur con el municipio de Puerto Morelos; y al este con el Mar Caribe.</p>\n<p>Esta posición lo vincula directamente con corredores productivos y zonas costeras estratégicas, de conformidad con los cuadros de construcción y el croquis de ubicación referidos en el artículo anterior.</p>","tipo_articulo":"ordinario","orden":5,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"2a560dae-fe24-50b4-ab2a-7c5cfb1e560b","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · II. Criterio de Comunicación y Conectividad","contenido":"<p>II. Criterio de Comunicación y Conectividad</p>\n<p>El polígono del PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN tiene acceso a mercados principales y ecosistemas productivos, se encuentra cercano a las carreteras 180 Matamoros - Cancún y 307 Reforma Agraria - Puerto Juárez que conecta directamente con el Distribuidor Colosio, a una distancia de 4.1 kilómetros de la estación del Tren Maya Cancún y en un rango de 5 kilómetros del Aeropuerto Internacional de Cancún, que es el segundo más importante del país por su tráfico total de pasajeros y el más importante por el tráfico de pasajeros internacionales y conectividad con otros países.</p>\n<p>Además de contar con una ubicación estratégica, el área destinada para el PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, dispone de acceso a servicios públicos necesarios, tales como energía eléctrica, telecomunicaciones, agua potable, alcantarillado y disponibilidad de agua renovable.</p>","tipo_articulo":"ordinario","orden":6,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"9677469f-044a-5066-a7a6-ba7ce3c1cd24","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · III. Criterio Poblacional","contenido":"<p>III. Criterio Poblacional</p>\n<p>El PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, se ubica en el municipio de Benito Juárez, estado de Quintana Roo, limita al norte con el municipio de Isla Mujeres; al oeste con el municipio de Lázaro Cárdenas; al sur con el municipio de Puerto Morelos; y al este con el Mar Caribe.</p>\n<p>Conforme al Censo de Población y Vivienda 2020(2), la población total de los municipios mencionados en el párrafo anterior es mayor a 50, 000 habitantes.</p>\n<table><thead><tr><th>Municipio Sede y Municipios Aledaños</th><th>Población Censo 2020</th><th>Población Total Municipio Sede y Municipios Aledaños</th></tr></thead><tbody><tr><td>Benito Juárez</td><td>911,503</td><td rowspan=\"4\">990,281</td></tr><tr><td>Isla Mujeres</td><td>22,686</td></tr><tr><td>Lázaro Cárdenas</td><td>29,171</td></tr><tr><td>Puerto Morelos</td><td>26,921</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":7,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"7912cc27-6b37-5fab-963e-7fe2bc775b00","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · IV. Criterio de Factibilidad Social","contenido":"<p>IV. Criterio de Factibilidad Social</p>\n<p>El Instituto Nacional de los Pueblos Indígenas mediante oficio CGDI/2026/OF/0250 de fecha 25 de febrero de 2026, informó lo siguiente:</p>\n<p>\"(...) De la revisión de los archivos en formato KMZ sobre la georreferenciación del proyecto, no se ubican localidades dentro de dicha superficie, así como tampoco tierras pertenecientes a un núcleo agrario certificado conforme a la información pública del Padrón e Historial de Núcleos Agrarios (PHINA) del Registro Agrario Nacional (....) Conforme a la información anterior, no se identifica comunidad indígena susceptible de afectar sus derechos territoriales con motivo de la implementación del proyecto antes referido. Por lo que, en opinión de este Instituto no es necesario realizar un proceso de consulta previa, libre e informada.\"</p>","tipo_articulo":"ordinario","orden":8,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"e9d0275a-5c1c-5ed2-8ff2-90d7c632190f","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · V. Criterio Educativo","contenido":"<p>V. Criterio Educativo</p>\n<p>En el PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, y los municipios aledaños a este, se localizan las siguientes instituciones de educación:</p>\n<table><thead><tr><th>Municipio</th><th>Institución de Educación Superior</th></tr></thead><tbody><tr><td>Benito Juárez</td><td>Andrés Quintana Roo</td></tr><tr><td>Benito Juárez</td><td>Centro de Estudios de Posgrado</td></tr><tr><td>Benito Juárez</td><td>Centro de Formación Profesional de Quintana Roo</td></tr><tr><td>Benito Juárez</td><td>Centro de Investigación Pedagógica del Caribe</td></tr><tr><td>Benito Juárez</td><td>Centro Universitario Zazil Kaanbal</td></tr><tr><td>Benito Juárez</td><td>Enseñanza e Investigación Superior, A.C.</td></tr><tr><td>Benito Juárez</td><td>Escuela Bancaria y Comercial, S.C.</td></tr><tr><td>Benito Juárez</td><td>Escuela Normal Superior Elvia Carrillo Puerto</td></tr><tr><td>Benito Juárez</td><td>Filma Centro Universitario de Artes Visuales Y Escénicas</td></tr><tr><td>Benito Juárez</td><td>Grupo Tecnológico Universitario</td></tr><tr><td>Benito Juárez</td><td>Instituto Mexicano de Educación Superior y Alta Dirección (IMESAD)</td></tr><tr><td>Benito Juárez</td><td>Instituto Pericial Judicial</td></tr><tr><td>Benito Juárez</td><td>Instituto Socrático Americano</td></tr><tr><td>Benito Juárez</td><td>Instituto Tecnológico de Cancún</td></tr><tr><td>Benito Juárez</td><td>Instituto Universitario de Alta Formación IUAF</td></tr><tr><td>Benito Juárez</td><td>Instituto Universitario del Centro de México</td></tr><tr><td>Benito Juárez</td><td>Instituto Universitario Kukulcán</td></tr><tr><td>Benito Juárez</td><td>Javier Rojo Gómez</td></tr><tr><td>Benito Juárez</td><td>Universidad Americana de Europa</td></tr><tr><td>Benito Juárez</td><td>Universidad Anáhuac - Cancún</td></tr><tr><td>Benito Juárez</td><td>Universidad Autónoma del Estado de Quintana Roo</td></tr><tr><td>Benito Juárez</td><td>Universidad Aztlán</td></tr><tr><td>Benito Juárez</td><td>Universidad de Oriente, A.C.</td></tr><tr><td>Benito Juárez</td><td>Universidad del Caribe</td></tr><tr><td>Benito Juárez</td><td>Universidad del Sur</td></tr><tr><td>Benito Juárez</td><td>Universidad Henbord</td></tr><tr><td>Benito Juárez</td><td>Universidad Humanitas S.C.</td></tr><tr><td>Benito Juárez</td><td>Universidad Interamericana para el Desarrollo</td></tr><tr><td>Benito Juárez</td><td>Universidad la Salle, A.C. - Cancún</td></tr><tr><td>Benito Juárez</td><td>Universidad Latinoamericana del Caribe</td></tr><tr><td>Benito Juárez</td><td>Universidad para la Cooperación Internacional México</td></tr><tr><td>Benito Juárez</td><td>Universidad Pedagógica Nacional Unidad 231 Chetumal</td></tr><tr><td>Benito Juárez</td><td>Universidad Politécnica de Quintana Roo</td></tr><tr><td>Benito Juárez</td><td>Universidad Santander</td></tr><tr><td>Benito Juárez</td><td>Universidad Tecnológica de Cancún</td></tr><tr><td>Benito Juárez</td><td>Universidad UCIEP</td></tr><tr><td>Benito Juárez</td><td>Universidad UNIMAAT</td></tr><tr><td>Benito Juárez</td><td>Universidad Unitech</td></tr><tr><td>Isla Mujeres</td><td>Instituto Superior de Estudios Creativos</td></tr><tr><td>Isla Mujeres</td><td>Universidad Sacro Cuore</td></tr><tr><td>Puerto Morelos</td><td>Instituto Yucatán Península Misión</td></tr><tr><td>Municipio</td><td>Institución de Educación Media Superior</td></tr><tr><td>Benito Juárez</td><td>Centro de Bachillerato Tecnológico Industrial y de Servicios (CBTIS) No. 111 \"Leona Vicario\"</td></tr><tr><td>Benito Juárez</td><td>Centro de Bachillerato Tecnológico Industrial y de Servicios (CBTIS) No. 272 \"Sor Juana Inés de la Cruz\"</td></tr><tr><td>Benito Juárez</td><td>Centro de Bachillerato Tecnológico Industrial y de Servicios (CBTIS) No. 302 \"Consuelo Zavala Castillo\"</td></tr><tr><td>Benito Juárez</td><td>Centro de Estudios Tecnológicos del Mar (CETMAR) No. 41</td></tr><tr><td>Benito Juárez</td><td>Colegio de Estudios Científicos y Tecnológicos del Estado (CECyTE) Plantel Cancún I</td></tr><tr><td>Benito Juárez</td><td>Colegio de Estudios Científicos y Tecnológicos del Estado (CECyTE) Plantel Cancún II</td></tr><tr><td>Benito Juárez</td><td>Colegio de Estudios Científicos y Tecnológicos del Estado (CECyTE) Plantel Cancún III</td></tr><tr><td>Benito Juárez</td><td>Colegio de Estudios Científicos y Tecnológicos del Estado (CECyTE) Plantel Cancún IV</td></tr><tr><td>Benito Juárez</td><td>Colegio Nacional de Educación Profesional (CONALEP) Cancún</td></tr><tr><td>Benito Juárez</td><td>Colegio Nacional de Educación Profesional (CONALEP) Cancún II</td></tr><tr><td>Benito Juárez</td><td>Colegio Nacional de Educación Profesional (CONALEP) Cancún III</td></tr><tr><td>Benito Juárez</td><td>Colegio Nacional de Educación Profesional (CONALEP) Cancún IV</td></tr><tr><td>Benito Juárez</td><td>Colegio de Bachilleres (COLBACH) Cancún Dos</td></tr><tr><td>Benito Juárez</td><td>Colegio de Bachilleres (COLBACH) Centro de Servicios Académicos Integrales Cancún</td></tr><tr><td>Benito Juárez</td><td>Colegio de Bachilleres (COLBACH) Plantel Cancún Cuatro</td></tr><tr><td>Benito Juárez</td><td>Colegio de Bachilleres (COLBACH) Plantel Cancún Uno</td></tr><tr><td>Isla Mujeres</td><td>Colegio de Bachilleres (COLBACH) Isla Mujeres</td></tr><tr><td>Isla Mujeres</td><td>Colegio de Bachilleres (COLBACH) Plantel Ciudad Mujeres</td></tr><tr><td>Puerto Morelos</td><td>Colegio de Estudios Científicos y Tecnológicos del Estado (CECyTE) Leona Vicario</td></tr><tr><td>Puerto Morelos</td><td>Colegio de Bachilleres (COLBACH) Plantel Puerto Morelos</td></tr><tr><td>Lázaro Cárdenas</td><td>Colegio de Bachilleres (COLBACH) Ignacio Zaragoza</td></tr><tr><td>Lázaro Cárdenas</td><td>Centro de Bachillerato Tecnológico Agropecuario Núm. 186</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":9,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"3bde51ab-63b4-546d-9925-4d43f72a6505","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · VI. Criterio Territorial","contenido":"<p>VI. Criterio Territorial</p>\n<p>De conformidad con el Programa de Desarrollo Urbano del Centro de Población (PDUCP) Cancún, municipio de Benito Juárez, la superficie destinada al PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, tiene asignado el uso de suelo \"Reserva Urbana 1\" clave RU1, cuya tabla de compatibilidad de uso de suelo admite, entre otros, usos comerciales, industriales y de servicios, por lo que las superficies identificadas y descritas en párrafos anteriores, presentan compatibilidad con los usos de suelo previstos para el Polo antes referido conforme al PDUCP.</p>\n<p>Para el desarrollo de las actividades productivas en el PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN y, conforme a la información proporcionada por el estado de Quintana Roo, aunado a los sectores productivos estratégicos de acuerdo con las vocaciones regionales, su vinculación con el entorno y su potencial desarrollo económico se determinan viables - de manera enunciativa más no limitativas - las siguientes vocaciones:</p>\n<p>1. Turismo médico;</p>\n<p>2. Producción audiovisual;</p>\n<p>3. Animación digital y contenidos;</p>\n<p>4. Servicios gastronómicos;</p>\n<p>5. Servicios educativos y formación profesional;</p>\n<p>6. Comercio al por mayor de alimentos y abarrotes;</p>\n<p>7. Centros de servicios empresariales y financieros, y</p>\n<p>8. Centros de distribución para el Caribe.</p>","tipo_articulo":"ordinario","orden":10,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"3f694693-ad34-5ae7-8fbe-e0cfaf182d23","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · VII. Criterio de Factibilidad Industrial","contenido":"<p>VII. Criterio de Factibilidad Industrial</p>\n<p>Conforme al PDUCP Cancún, municipio de Benito Juárez, la porción de los polígonos destinados para la implementación del PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN, tiene asignado el uso de suelo \"Reserva Urbana 1\" clave RU1, cuya tabla de compatibilidad de uso de suelo admite entre otros, usos comerciales, industriales y de servicios.</p>","tipo_articulo":"ordinario","orden":11,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"0f20583a-2721-57a4-b992-f88b07f41556","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · VIII. Criterio de Sostenibilidad","contenido":"<p>VIII. Criterio de Sostenibilidad</p>\n<p>La Secretaría de Medio Ambiente y Recursos Naturales, mediante oficio núm. SDSEC/800/0046/2026 de fecha 17 de marzo de 2026, determinó que el PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN es \"(...) viable en materia ambiental, sujeto al cumplimiento de los requisitos normativos aplicables y a la integración de medidas específicas para protección ecológica y gestión hídrica (...)\".</p>\n<p>En el mismo sentido, la Comisión Nacional de Áreas Naturales Protegidas, a través de la Dirección Regional Península de Yucatán y Caribe Mexicano informó mediante Oficio No. F00.9.DRPYyCM.SUTCMR.-047/2026 que \"ambos predios, se localizan fuera de algún área natural protegida federal, quedando a una distancia de separación de 7.0 Km respecto del Área Destinada Voluntariamente a la Conservación (ADVC) \"Reserva Privada Moon Palace\" y a 7.2 Km del Área de Protección de Flora y Fauna Manglares de Nichupté.\"</p>","tipo_articulo":"ordinario","orden":12,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"af4b807a-4218-55d3-8411-44792b92e259","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · IX. Criterio de Servicios e Infraestructura","contenido":"<p>IX. Criterio de Servicios e Infraestructura</p>\n<p>El polígono cuenta con los servicios e infraestructura básicos para el desarrollo de las actividades productivas. Dispone de vialidades, energía eléctrica, agua potable, drenaje y conectividad, con opciones identificadas para ampliar la disponibilidad de energía en el mediano plazo, lo que garantiza condiciones adecuadas para la operación de empresas e industrias, y contribuye al impulso del desarrollo regional y la atracción de inversiones.</p>","tipo_articulo":"ordinario","orden":13,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"49e1010b-7641-5d8a-99a3-ec372d578ffd","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · X. Criterio de Propiedad","contenido":"<p>X. Criterio de Propiedad</p>\n<p>De la información proporcionada por la entidad federativa y la documentación que fue puesta a disposición del Comité Intersecretarial de Promoción, se desprende que los predios que conforman el área destinada al PODECOBI DISTRITO FINANCIERO Y TECNOLÓGICO DE CANCÚN son bienes del dominio público del estado de Quintana Roo.</p>","tipo_articulo":"ordinario","orden":14,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"30c0ec43-dc17-5b75-9393-ad3e1f6d88ed","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo tercero · XI. Criterio de Habitabilidad","contenido":"<p>XI. Criterio de Habitabilidad</p>\n<p>El Gobierno del estado de Quintana Roo, informó que los predios están a 8 km del punto más cercano de transporte público urbano, por lo que sería necesario extender las rutas de transporte público y mejorar la infraestructura peatonal para garantizar un acceso seguro y equitativo a los servicios urbanos, por lo que aumentarán la cobertura de transporte público, misma que se encuentra en proceso de elaboración del Plan Integral de Movilidad Urbana Sustentable (PIMUS) Cancún - Isla Mujeres.</p>","tipo_articulo":"ordinario","orden":15,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"c2797ff5-6737-51c8-920f-5a007dec34f4","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Artículo cuarto","contenido":"<p>ARTÍCULO CUARTO. El estado de Quintana Roo y la Secretaría de Economía deberán suscribir el convenio de coordinación a que se refiere el artículo Décimo, párrafo tercero del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.</p>","tipo_articulo":"ordinario","orden":16,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"93647c2a-e023-5a3c-bfe8-e6b9711c1c00","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Transitorio único","contenido":"<p>TRANSITORIO</p>\n<p>ÚNICO. La presente Declaratoria entra en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.</p>","tipo_articulo":"transitorio","orden":17,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"3af9d206-32cc-53b3-a906-c0814b9ba700","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Firma del acuerdo","contenido":"<p>Ciudad de México, a 04 de agosto de 2026.- El Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.</p>","tipo_articulo":"complementario","orden":18,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1cb7f585-fae4-5d1b-a952-c9beb9c519a4","ley_id":"172a0b68-5ef3-5a43-841f-eecf288f0894","identificador":"Notas al pie","contenido":"<p>1 https://www.gob.mx/cms/uploads/attachment/file/981072/PND_2025-2030_v250226_14.pdf</p>\n<p>2 Inegi (2020). Censo de Población y Vivienda 2020. Instituto Nacional de Estadística y Geografía (INEGI). https://www.inegi.org.mx/</p>","tipo_articulo":"nota","orden":19,"titulo_nombre":"Distrito Financiero y Tecnológico de Cancún","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
END
$carga$;
